## CTA Button

```tsx
// CTAButton.tsx
import { interpolate, spring, useCurrentFrame, useVideoConfig } from 'remotion';

export const CTAButton = ({
  text = "Get Started",
  url = "#",
  delay = 0,
}: {
  text?: string;
  url?: string;
  delay?: number;
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const scale = spring({
    frame: frame - delay,
    fps,
    from: 0,
    to: 1,
    config: { damping: 12 },
  });

  return (
    <a href={url} style={{
      display: 'inline-block',
      padding: '16px 32px',
      background: 'linear-gradient(90deg, #667eea, #764ba2)',
      color: 'white',
      borderRadius: 8,
      fontSize: 18,
      fontWeight: 'bold',
      textDecoration: 'none',
      transform: `scale(${scale})`,
    }}>
      {text}
    </a>
  );
};
```

