## Green Screen / Chroma Key

```tsx
export const ChromaKey = ({ video, color = '#00ff00' }) => {
  return (
    <div style={{ backgroundColor: color, mixBlendMode: 'multiply' }}>
      {video}
    </div>
  );
};
