## Progress Indicator

```tsx
const ProgressBar = ({ progress }: { progress: number }) => {
  return (
    <div style={{
      width: `${progress * 100}%`,
      height: 4,
      background: 'linear-gradient(90deg, #667eea, #764ba2)',
    }} />
